    background: linear-gradient(135deg, #fac273 0%, #e2a03f 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: none;
    border: 3px solid #ffffff;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    color: #485349;
}

.mnav-fab i {
    font-size: 22px;
    line-height: 1;
    color: #485349;
    display: block;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}



.mnav-center:hover .mnav-fab,
.mnav-center.is-active .mnav-fab {
    transform: translateY(-4px) scale(1.08);
    box-shadow: none;
}

.mnav-center.is-active .mnav-fab {
    background: linear-gradient(135deg, #e2a03f 0%, #c8882a 100%);
}

.mnav-center.is-active .mnav-fab::before {
    border-color: rgba(250, 194, 115, 0.35);
    inset: -7px;
}

.mnav-center:active .mnav-fab {
    transform: scale(0.92);
}

.mnav-center .mnav-label {
    margin-top: 24px;
    font-size: 10px;
    font-weight: 600;
    color: #b0bac4;
    letter-spacing: 0.01em;
}

.mnav-center.is-active .mnav-label {
    color: #e2a03f;
}

/* Mobile Scrollable Filter Tabs & Squish Fixes */
.filter-tabs {
    display: flex !important;
    flex-wrap: nowrap !important;
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch;
    width: 100% !important;
}

.filter-tabs::-webkit-scrollbar {
    display: none !important; /* Hide scrollbar */
}

.filter-tabs {
    -ms-overflow-style: none;  /* IE and Edge */
    scrollbar-width: none;  /* Firefox */
}

.btn-filter-tab {
    flex-shrink: 0 !important;
}

/* Hide Sidebar / Drawer on Mobile Viewports */
@media (max-width: 991.98px) {
    #kt_aside, 
    #kt_aside_toggle,
    .aside,
    [data-kt-drawer-name="aside"] {
        display: none !important;
    }
}

