/* ==========================================================================
   Invitation List Page — Redesign
   ========================================================================== */

/* ── Page Header ── */
.inv-page-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}

.inv-page-header-left {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.inv-page-title {
    font-size: 1.6rem;
    font-weight: 800;
    color: #0f172a;
    margin: 0;
    line-height: 1.2;
}

.inv-page-subtitle {
    font-size: 0.875rem;
    color: #64748b;
    margin: 0;
}

.inv-page-header-right {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}

/* Layout Toggle Button */
.inv-layout-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 10px;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    color: #485349;
    font-size: 18px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.inv-layout-btn:hover {
    background: #f8fafc;
    border-color: #cbd5e1;
}

/* Create Button */
.inv-create-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 10px 20px;
    border-radius: 10px;
    background: #fac273;
    color: #485349;
    font-size: 13.5px;
    font-weight: 700;
    border: none;
    cursor: pointer;
    text-decoration: none !important;
    transition: all 0.2s ease;
    height: 40px;
}

.inv-create-btn:hover {
    background: #e2a03f;
    color: #485349;
}

.inv-create-btn i {
    font-size: 16px;
}

/* ── Grid Layout ── */
.inv-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    margin-bottom: 24px;
}

/* ── Invitation Card ── */
.inv-card-v3 {
    background: #ffffff;
    border: 1px solid #f1f5f9;
    border-radius: 18px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    transition: border-color 0.2s ease, transform 0.2s ease;
}

.inv-card-v3:hover {
    border-color: #e2e8f0;
    transform: translateY(-2px);
}

/* Card Top */
.inv-card-top {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 14px 16px 0;
}

/* Status badge */
.inv-card-status {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 4px 10px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.02em;
}

.inv-card-status-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    display: inline-block;
}

.inv-card-status-active  { background: #dcfce7; color: #16a34a; }
.inv-card-status-active .inv-card-status-dot  { background: #22c55e; }
.inv-card-status-draft   { background: #fef9c3; color: #a16207; }
.inv-card-status-draft .inv-card-status-dot   { background: #eab308; }
.inv-card-status-inactive{ background: #e0f2fe; color: #0369a1; }
.inv-card-status-inactive .inv-card-status-dot{ background: #0ea5e9; }
.inv-card-status-danger  { background: #fee2e2; color: #dc2626; }
.inv-card-status-danger .inv-card-status-dot  { background: #ef4444; }

/* Card Menu Button */
.inv-card-menu-btn-v3 {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    border-radius: 8px;
    background: transparent;
    border: none;
    color: #94a3b8;
    font-size: 18px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.inv-card-menu-btn-v3:hover {
    background: #f1f5f9;
    color: #475569;
}

/* Card Middle */
.inv-card-middle {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 14px 16px 10px;
    flex: 1;
}

.inv-card-thumb-v3 {
    width: 72px;
    height: 72px;
    border-radius: 12px;
    object-fit: cover;
    flex-shrink: 0;
    border: 1px solid #f1f5f9;
}

.inv-card-thumb-placeholder-v3 {
    width: 72px;
    height: 72px;
    border-radius: 12px;
    background: #f8fafc;
    border: 1px dashed #e2e8f0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #cbd5e1;
    font-size: 24px;
    flex-shrink: 0;
}

.inv-card-details-v3 {
    display: flex;
    flex-direction: column;
    gap: 5px;
    min-width: 0;
    flex: 1;
}

.inv-card-title-v3 {
    font-size: 0.925rem;
    font-weight: 700;
    color: #1e293b;
    margin: 0;
    line-height: 1.3;
    max-width: 100%;
}

.inv-card-meta-v3 {
    display: flex;
    align-items: center;
    gap: 5px;
    font-size: 11.5px;
    color: #64748b;
    font-weight: 500;
}

.inv-card-meta-v3 i {
    color: #94a3b8;
    font-size: 13px;
    flex-shrink: 0;
}

/* RSVP Row */
.inv-card-rsvp-row-v3 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 16px 12px;
    background: #fafbfc;
    border-top: 1px solid #f1f5f9;
}

.rsvp-left-v3 {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    color: #94a3b8;
    font-weight: 500;
}

.rsvp-left-v3 i {
    font-size: 16px;
    color: #cbd5e1;
}

.rsvp-right-v3 {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    line-height: 1;
}

.rsvp-count-v3 {
    font-size: 1.5rem;
    font-weight: 800;
    color: #fac273;
    line-height: 1;
}

.rsvp-label-v3 {
    font-size: 9px;
    font-weight: 700;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-top: 2px;
}

/* Card Footer */
.inv-card-footer-v3 {
    display: flex;
    border-top: 1px solid #f1f5f9;
}

.inv-card-btn-v3 {
    flex: 1;
    border: none;
    background: transparent;
    padding: 12px 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
    text-decoration: none !important;
    cursor: pointer;
    transition: all 0.18s ease;
    -webkit-tap-highlight-color: transparent;
}

.inv-card-btn-v3:not(:last-child) {
    border-right: 1px solid #f1f5f9;
}

.inv-card-btn-v3:hover {
    background: #f8fafc;
    color: #1e293b;
}

.inv-card-btn-v3.inv-card-btn-primary {
    color: #e2a03f;
    font-weight: 700;
}

.inv-card-btn-v3.inv-card-btn-primary:hover {
    background: #fffbeb;
    color: #c8882a;
}

.inv-card-btn-v3 i {
    font-size: 14px;
}

/* ── Table Layout ── */
.inv-table-wrap {
    background: #ffffff;
    border: 1px solid #f1f5f9;
    border-radius: 16px;
    overflow: hidden;
}

.inv-table-thumb {
    display: block;
    width: 44px;
    height: 44px;
    border-radius: 10px;
    overflow: hidden;
    flex-shrink: 0;
    border: 1px solid #f1f5f9;
    text-decoration: none;
}

.inv-table-thumb img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    display: block;
}

.inv-table-thumb-plain {
    display: block;
    width: 44px;
    height: 44px;
    border-radius: 10px;
    overflow: hidden;
    flex-shrink: 0;
    border: 1px solid #f1f5f9;
    opacity: 0.6;
}

.inv-table-title {
    font-size: 13.5px;
    font-weight: 700;
    color: #1e293b;
    text-decoration: none !important;
    transition: color 0.15s ease;
    line-height: 1.3;
}

a.inv-table-title:hover {
    color: #e2a03f;
}

/* Table base */
.se-table {
    width: 100%;
    border-collapse: collapse;
}

.se-table thead tr {
    background: rgba(72, 83, 73, 0.04);
}

.se-table th {
    padding: 14px 20px;
    font-weight: 700;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #485349;
    border-bottom: 1px solid #f1f5f9;
    white-space: nowrap;
}

.se-table td {
    padding: 14px 20px;
    vertical-align: middle;
    border-bottom: 1px solid #f1f5f9;
    font-size: 13px;
    color: #475569;
}

.se-table tbody tr:last-child td {
    border-bottom: none;
}

.se-table tbody tr:hover td {
    background: rgba(250, 194, 115, 0.03);
}

/* Badges */
.se-badge {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 4px 10px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.02em;
}

.se-badge-success { background: #dcfce7; color: #16a34a; }
.se-badge-warning { background: #fef9c3; color: #a16207; }
.se-badge-info    { background: #e0f2fe; color: #0369a1; }
.se-badge-danger  { background: #fee2e2; color: #dc2626; }

/* Table action buttons */
.se-btn-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    height: 32px;
    padding: 0 12px;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 700;
    text-decoration: none !important;
    transition: all 0.18s ease;
    cursor: pointer;
    border: none;
}

.se-btn-primary {
    background: #fac273;
    color: #485349;
}
.se-btn-primary:hover {
    background: #e2a03f;
    color: #485349;
}

.se-btn-secondary {
    background: #f8fafc;
    color: #475569;
    border: 1px solid #e2e8f0;
}
.se-btn-secondary:hover {
    background: #f1f5f9;
    color: #1e293b;
    border-color: #cbd5e1;
}

/* ── Empty State ── */
.inv-empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 60px 20px;
    text-align: center;
    background: #ffffff;
    border: 1px solid #f1f5f9;
    border-radius: 18px;
}

.inv-empty-icon {
    width: 80px;
    height: 80px;
    border-radius: 24px;
    background: #f8fafc;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 40px;
    color: #cbd5e1;
    margin-bottom: 20px;
}

.inv-empty-title {
    font-size: 1.1rem;
    font-weight: 700;
    color: #1e293b;
    margin: 0 0 8px;
}

.inv-empty-desc {
    font-size: 13px;
    color: #94a3b8;
    margin: 0 0 20px;
    max-width: 300px;
}

/* ── Mobile Responsive ── */
@media (max-width: 991.98px) {
    .inv-page-header {
        margin-bottom: 14px;
    }

    .inv-page-title {
        font-size: 1.25rem;
    }

    .inv-page-subtitle {
        display: none;
    }

    .inv-grid {
        grid-template-columns: 1fr;
        gap: 12px;
    }

    .inv-create-btn span {
        display: none;
    }

    .inv-create-btn {
        width: 40px;
        padding: 0;
        justify-content: center;
    }

    .inv-table-wrap {
        border-radius: 12px;
        overflow-x: auto;
    }
}

/* ==========================================================================
   Invitation Filter Bar (card-header.php)
   ========================================================================== */

/* Wrapper — single row, never wraps, no overflow on parent */
.card-header-filter-v3 {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 20px;
    flex-wrap: nowrap;
    min-width: 0;
}

/* ── Filter Tabs — scrollable internally ── */
.card-header-filter-v3 .filter-tabs {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: nowrap;
    flex: 1;
    min-width: 0;
    overflow-x: auto;
    -ms-overflow-style: none;
    scrollbar-width: none;
    padding-bottom: 1px;
}

.card-header-filter-v3 .filter-tabs::-webkit-scrollbar {
    display: none;
}

/* Tab button base */
.btn-filter-tab {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 14px;
    border-radius: 999px;
    font-size: 13px;
    font-weight: 600;
    border: 1px solid #e2e8f0;
    background: #ffffff;
    color: #64748b;
    white-space: nowrap;
    text-decoration: none !important;
    transition: all 0.18s ease;
    flex-shrink: 0;
    cursor: pointer;
    line-height: 1;
}

.btn-filter-tab:hover {
    border-color: #cbd5e1;
    color: #1e293b;
    background: #f8fafc;
}

/* Active states per tab */
.btn-filter-tab.active-all {
    background: #fac273;
    border-color: #fac273;
    color: #485349;
}

.btn-filter-tab.active-active {
    background: #dcfce7;
    border-color: #86efac;
    color: #16a34a;
}

.btn-filter-tab.active-draft {
    background: #fef9c3;
    border-color: #fde047;
    color: #a16207;
}

.btn-filter-tab.active-archive {
    background: #e0f2fe;
    border-color: #7dd3fc;
    color: #0369a1;
}

/* Status dot inside tabs */
.btn-filter-tab .status-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    display: inline-block;
    flex-shrink: 0;
}

.btn-filter-tab .status-dot.bg-success {
    background: #22c55e !important;
}

/* ── Controls Group ── */
.card-header-filter-v3 .filter-controls {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
    margin-left: auto;
    padding-left: 4px;
}

/* Divider between tabs and controls */
.card-header-filter-v3 .filter-divider {
    width: 1px;
    height: 22px;
