    background: #f8fafc;
    outline: none;
    width: 100%;
    font-family: 'Plus Jakarta Sans', sans-serif;
    transition: border-color 0.2s ease, background 0.2s ease;
}

.stg-input:focus {
    border-color: #fac273;
    background: #ffffff;
}

.stg-input-disabled {
    background: #f1f5f9 !important;
    color: #94a3b8 !important;
    cursor: not-allowed;
}

/* File input */
.stg-input-file {
    height: auto !important;
    padding: 10px 14px !important;
    cursor: pointer;
}

/* Input with prefix icon */
.stg-input-prefix-wrap {
    position: relative;
}

.stg-input-prefix-icon {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 15px;
    color: #94a3b8;
    pointer-events: none;
}

.stg-input-prefixed {
    padding-left: 36px !important;
}

/* Hint text */
.stg-hint {
    font-size: 11.5px;
    color: #94a3b8;
    font-weight: 500;
}

/* Logo preview */
.stg-logo-preview {
    max-height: 64px;
    border-radius: 10px;
    border: 1px solid #f1f5f9;
    padding: 4px;
    background: #ffffff;
    display: block;
