/* ── Save Button ── */
.stg-btn-save {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    height: 40px;
    padding: 0 20px;
    border-radius: 10px;
    background: #fac273;
    border: none;
    color: #485349;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
    font-family: 'Plus Jakarta Sans', sans-serif;
    transition: background 0.18s ease;
}

.stg-btn-save:hover {
    background: #e2a03f;
}

.stg-btn-save-sm {
    height: 36px;
    font-size: 12.5px;
    padding: 0 16px;
}

/* Change button */
.stg-btn-change {
    height: 34px;
    padding: 0 14px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
    background: #f8fafc;
    color: #475569;
    font-size: 12.5px;
    font-weight: 600;
    cursor: pointer;
    font-family: 'Plus Jakarta Sans', sans-serif;
    white-space: nowrap;
